import { gameManager, settingsManager } from 'src/app/game/businesslogic/Managers';
import { ActionHex, ActionHexFromString, ActionHexType } from 'src/app/game/model/ActionHex';
import { Character, GameCharacterModel } from 'src/app/game/model/Character';
import { Action, ActionType } from 'src/app/game/model/data/Action';
import { ConditionName } from 'src/app/game/model/data/Condition';
import { Element } from 'src/app/game/model/data/Element';
import { Enhancement, EnhancementAction } from 'src/app/game/model/data/Enhancement';
import { PersonalQuestAutotrackType } from 'src/app/game/model/data/PersonalQuest';
import { Game } from 'src/app/game/model/Game';

export class EnhancementsManager {
  game: Game;
  fh: boolean = false;
  temporary: boolean = false;
  enhancerLevel: number = 0;

  squareActions: ActionType[] = [
    ActionType.move,
    ActionType.attack,
    ActionType.range,
    ActionType.shield,
    ActionType.push,
    ActionType.pull,
    ActionType.pierce,
    ActionType.retaliate,
    ActionType.heal,
    ActionType.target,
    ActionType.teleport
  ];
  circleActions: ActionType[] = [
    ActionType.move,
    ActionType.attack,
    ActionType.range,
    ActionType.shield,
    ActionType.push,
    ActionType.pull,
    ActionType.pierce,
    ActionType.retaliate,
    ActionType.heal,
    ActionType.target,
    ActionType.teleport
  ];
  diamondActions: ActionType[] = [ActionType.attack, ActionType.condition, ActionType.push, ActionType.pull];
  diamondPlusActions: ActionType[] = [ActionType.heal, ActionType.condition, ActionType.shield, ActionType.retaliate];
  hexActions: ActionType[] = [ActionType.area];
  summonActions: ActionType[] = [ActionType.move, ActionType.attack, ActionType.range, ActionType.heal];
  diamondConditions: ConditionName[] = [
    ConditionName.poison,
    ConditionName.wound,
    ConditionName.muddle,
    ConditionName.immobilize,
    ConditionName.disarm,
    ConditionName.curse
  ];
  diamondPlusConditions: ConditionName[] = [ConditionName.strengthen, ConditionName.bless, ConditionName.regenerate];

  constructor(game: Game) {
    this.game = game;
  }

  update() {
    this.fh = gameManager.fhRules(true) || settingsManager.settings.alwaysFhEnhancements;
    this.temporary = settingsManager.settings.temporaryEnhancements;
    this.enhancerLevel =
      (this.fh &&
        this.game.party.buildings.find(
          (buildingModel) => buildingModel.name === 'enhancer' && buildingModel.level && buildingModel.state !== 'wrecked'
        )?.level) ||
      0;
    if (this.fh) {
      this.diamondConditions = [
        ConditionName.poison,
        ConditionName.wound,
        ConditionName.muddle,
        ConditionName.immobilize,
        ConditionName.curse
      ];
      this.diamondPlusConditions = [ConditionName.strengthen, ConditionName.bless, ConditionName.regenerate, ConditionName.ward];
    } else {
      this.diamondConditions = [
        ConditionName.poison,
        ConditionName.wound,
        ConditionName.muddle,
        ConditionName.immobilize,
        ConditionName.disarm,
        ConditionName.curse
      ];
      this.diamondPlusConditions = [ConditionName.strengthen, ConditionName.bless, ConditionName.regenerate];
    }
  }

  isMultiTarget(action: Action, rootAction: Action) {
    if (this.fh && [ActionType.target, ActionType.area, ActionType.element].includes(action.type)) {
      return false;
    } else if (action.type === ActionType.area) {
      return false;
    }
    return gameManager.actionsManager.hasMultiTarget(rootAction);
  }

  calculateCosts(
    action: Action,
    rootAction: Action,
    level: number = 1,
    special: 'summon' | 'lost' | 'persistent' | undefined,
    enhancements: number,
    temporaryOff: boolean = false
  ): number {
    let costs = 0;
    costs += this.calculateBaseCosts(action, special);

    if (costs > 0) {
      // double multi target
      if (this.isMultiTarget(action, rootAction)) {
        costs *= 2;
      }

      if (this.fh && special === 'lost') {
        costs = Math.ceil(costs / 2);
      }

      if (this.fh && !gameManager.gh2eRules() && special === 'persistent') {
        costs *= 3;
      }

      // level costs
      costs += this.levelCosts(level);
      // enhancements costs
      costs += this.enhancementCosts(enhancements);

      if (this.fh && this.temporary) {
        if (enhancements) {
          costs -= 20;
        }
        if (!temporaryOff) {
          costs = Math.ceil(costs * 0.8);
        }
      }

      if (this.enhancerLevel > 1 && !temporaryOff) {
        costs -= 10;
      }
    }

    return costs;
  }

  calculateBaseCosts(action: Action, special: 'summon' | 'lost' | 'persistent' | undefined = undefined): number {
    let costs = 0;
    if (special === 'summon') {
      switch (action.type) {
        case ActionType.move:
          costs += this.fh ? 60 : this.temporary ? 40 : 100;
          break;
        case ActionType.attack:
          costs += !this.fh && this.temporary ? 60 : 100;
          break;
        case ActionType.range:
          costs += !this.fh && this.temporary ? 40 : 50;
          break;
        case ActionType.heal: // as HP
          costs += this.fh ? 40 : this.temporary ? 30 : 50;
          break;
      }
    } else {
      switch (action.type) {
        case ActionType.move:
          costs += !this.fh && this.temporary ? 20 : 30;
          break;
        case ActionType.attack:
          costs += !this.fh && this.temporary ? 35 : 50;
          break;
        case ActionType.range:
          costs += !this.fh && this.temporary ? 20 : 30;
          break;
        case ActionType.target:
          costs += this.fh ? 75 : this.temporary ? 40 : 50;
          break;
        case ActionType.shield:
          costs += this.fh ? 80 : this.temporary ? 60 : 100;
          break;
        case ActionType.retaliate:
          costs += this.fh ? 60 : this.temporary ? 40 : 100;
          break;
        case ActionType.pierce:
          costs += !this.fh && this.temporary ? 15 : 30;
          break;
        case ActionType.heal:
          costs += !this.fh && this.temporary ? 20 : 30;
          break;
        case ActionType.push:
          costs += !this.fh && this.temporary ? 20 : 30;
          break;
        case ActionType.pull:
          costs += this.fh ? 20 : this.temporary ? 15 : 30;
          break;
        case ActionType.teleport:
          costs += this.fh ? 50 : 40;
          break;
        case ActionType.jump:
          costs += this.fh ? 60 : this.temporary ? 35 : 50;
          break;
        case ActionType.element:
          if ((action.value as Element) !== Element.wild) {
            costs += !this.fh && this.temporary ? 60 : 100;
          } else {
            costs += !this.fh && this.temporary ? 90 : 150;
          }
          break;
        case ActionType.condition: {
          switch (action.value as ConditionName) {
            case ConditionName.poison:
              costs += this.fh ? 50 : this.temporary ? 30 : 75;
              break;
            case ConditionName.wound:
              costs += !this.fh && this.temporary ? 45 : 75;
              break;
            case ConditionName.muddle:
              costs += this.fh ? 40 : this.temporary ? 25 : 50;
              break;
            case ConditionName.immobilize:
              costs += this.fh ? 150 : 100;
              break;
            case ConditionName.disarm:
              costs += this.fh ? 0 : 150;
              break;
            case ConditionName.curse:
              costs += this.fh ? 150 : this.temporary ? 100 : 75;
              break;
            case ConditionName.strengthen:
              costs += this.fh ? 100 : this.temporary ? 100 : 50;
              break;
            case ConditionName.bless:
              costs += this.fh ? 75 : 50;
              break;
            case ConditionName.regenerate:
              costs += this.fh ? 40 : 50;
              break;
            case ConditionName.ward:
              costs += this.fh ? 75 : 0;
              break;
          }
          break;
        }
        case ActionType.area: {
          const hexes: ActionHex[] = ('' + action.value)
            .split('|')
            .map((value) => ActionHexFromString(value))
            .filter((value) => value)
            .map((value) => value as ActionHex);
          costs += Math.ceil(200 / (hexes.filter((actionHex) => actionHex.type === ActionHexType.target).length || 1));
          break;
        }
      }
    }

    return costs;
  }

  levelCosts(level: number): number {
    if (level < 1) {
      level = 1;
    } else if (level > 9) {
      level = 9;
    }
    return (level - 1) * (!this.fh && this.temporary ? 10 : this.enhancerLevel > 2 ? 15 : 25);
  }

  enhancementCosts(enhancements: number): number {
    if (enhancements < 0) {
      enhancements = 0;
    }
    return enhancements * (!this.fh && this.temporary ? 20 : this.enhancerLevel > 3 ? 50 : 75);
  }

  cardEnhancements(character: Character, cardId: number, actionIndex: string): number {
    return (character.progress.enhancements || []).filter(
      (enhancement) => enhancement.cardId === cardId && enhancement.actionIndex.indexOf('bottom') === actionIndex.indexOf('bottom')
    ).length;
  }

  enhancedCards(character: Character, excludeCardId: number | undefined = undefined): number {
    return (character.progress.enhancements || [])
      .filter((enhancement) => !enhancement.inherited)
      .map((enhancement) => enhancement.cardId)
      .filter((cardId, index, self) => (!excludeCardId || excludeCardId !== cardId) && index === self.indexOf(cardId)).length;
  }

  enhancementsAvailable(): boolean {
    if (!gameManager.editionManager.currentEdition()) {
      return true;
    }
    if (gameManager.fhRules()) {
      return this.game.party.buildings.some(
        (buildingModel) => buildingModel.name === 'enhancer' && buildingModel.level > 0 && buildingModel.state !== 'wrecked'
      );
    }
    if (gameManager.editionRules('gh') || gameManager.gh2eRules()) {
      return this.game.party.globalAchievementsList.some((achievement) => achievement.toLowerCase().trim() === 'the-power-of-enhancement');
    }
    return true;
  }

  canEnhance(character: Character, cardId: number, costs: number): boolean {
    return (
      this.enhancementsAvailable() &&
      character.progress.gold >= costs &&
      (this.fh || this.enhancedCards(character, cardId) < gameManager.campaignManager.prosperityLevel())
    );
  }

  canAddEnhancement(
    character: Character,
    cardId: number,
    actionIndex: string,
    index: number,
    costs: number = 0,
    force: boolean = false
  ): boolean {
    return (
      Number.isInteger(costs) &&
      costs >= 0 &&
      !(character.progress.enhancements || []).some(
        (enhancement) => enhancement.cardId === cardId && enhancement.actionIndex === actionIndex && enhancement.index === index
      ) &&
      (force || this.canEnhance(character, cardId, costs))
    );
  }

  addEnhancement(
    character: Character,
    cardId: number,
    actionIndex: string,
    index: number,
    action: EnhancementAction,
    costs: number = 0,
    force: boolean = false
  ): boolean {
    if (!this.canAddEnhancement(character, cardId, actionIndex, index, costs, force)) {
      return false;
    }
    character.progress.enhancements = character.progress.enhancements || [];
    character.progress.enhancements.push(new Enhancement(cardId, actionIndex, index, action));
    gameManager.personalQuestManager.trackPersonalQuestProgress(character, PersonalQuestAutotrackType.enhancements);
    character.progress.gold -= costs;
    return true;
  }

  removeEnhancement(character: Character, enhancement: Enhancement) {
    character.progress.enhancements = character.progress.enhancements.filter((other) => other !== enhancement);
  }

  // change enhancements of a retired character, an active character of the same class inherits them again
  setRetiredEnhancements(characterModel: GameCharacterModel, enhancements: Enhancement[]): boolean {
    if (!characterModel.progress || !Array.isArray(enhancements)) {
      return false;
    }
    characterModel.progress.enhancements = enhancements;
    const current = this.game.figures.find(
      (figure) => figure instanceof Character && figure.edition === characterModel.edition && figure.name === characterModel.name
    ) as Character | undefined;
    if (current) {
      this.previousEnhancements(current, this.temporary);
    }
    return true;
  }

  previousEnhancements(character: Character, temporary: boolean) {
    if (character.progress.enhancements) {
      character.progress.enhancements = character.progress.enhancements.filter((e) => !e.inherited);
    } else {
      character.progress.enhancements = [];
    }
    if (!temporary) {
      const previousCharacters = this.game.party.retirements.filter(
        (model) => model.edition === character.edition && model.name === character.name
      );
      previousCharacters.forEach((previousCharacter) => {
        if (previousCharacter && previousCharacter.progress && previousCharacter.progress.enhancements) {
          character.progress.enhancements.push(
            ...previousCharacter.progress.enhancements
              .filter((e) => !e.inherited)
              .map((e) => new Enhancement(e.cardId, e.actionIndex, e.index, e.action, true))
          );
        }
      });

      character.progress.enhancements = character.progress.enhancements.filter((e, index, self) => {
        const first = self.find((o) => o.cardId === e.cardId && o.actionIndex === e.actionIndex && o.index === e.index);
        return !first || index === self.indexOf(first);
      });
    }

    // wipSpecial
    character.progress.enhancements
      .filter((e) => e.actionIndex.includes('custom'))
      .forEach((e) => {
        const card = gameManager.editionManager.deckData(character).abilities.find((a) => a.cardId === e.cardId);
        if (card) {
          const mapping = this.enhancementMapping(
            !e.actionIndex.includes('bottom') ? card.actions : card.bottomActions || [],
            !e.actionIndex.includes('bottom') ? '' : 'bottom'
          );
          if (mapping.length && mapping[e.index]) {
            e.actionIndex = mapping[e.index];
            e.index = e.index - mapping.indexOf(e.actionIndex);
          }
        }
      });
  }

  enhancementMapping(actions: Action[], parentIndex: string): string[] {
    const mapping: string[] = [];
    actions.forEach((action, index) => {
      if (action.type !== ActionType.custom || action.value !== '%character.abilities.wip%') {
        const actionId = (parentIndex ? parentIndex + '-' : '') + index;
        if (action.enhancementTypes) {
          action.enhancementTypes.forEach(() => {
            mapping.push(actionId);
          });
        }
        if (action.subActions) {
          mapping.push(...this.enhancementMapping(action.subActions, actionId));
        }
      }
    });

    return mapping;
  }
}
