import { moveItemInArray } from '@angular/cdk/drag-drop';
import { gameManager, settingsManager } from 'src/app/game/businesslogic/Managers';
import { BuildingModel } from 'src/app/game/model/Building';
import { Character } from 'src/app/game/model/Character';
import { Action, ActionType, ActionValueType } from 'src/app/game/model/data/Action';
import { AttackModifier, AttackModifierEffect, AttackModifierEffectType, AttackModifierType } from 'src/app/game/model/data/AttackModifier';
import { ChallengeCard, ChallengeDeck } from 'src/app/game/model/data/Challenges';
import { CharacterData } from 'src/app/game/model/data/CharacterData';
import { Condition, ConditionName, ConditionType, EntityConditionState } from 'src/app/game/model/data/Condition';
import { Identifier } from 'src/app/game/model/data/Identifier';
import { MonsterType } from 'src/app/game/model/data/MonsterType';
import { EntityValueFunction } from 'src/app/game/model/Entity';
import { Game, GameState } from 'src/app/game/model/Game';
import { Monster } from 'src/app/game/model/Monster';

export class ChallengesManager {
  game: Game;
  available: boolean = false;
  enabled: boolean = false;
  apply: boolean = false;

  constructor(game: Game) {
    this.game = game;
  }

  townHall(): BuildingModel | undefined {
    return this.game.party.buildings.find((model) => model.name === 'town-hall' && model.level && model.state !== 'wrecked');
  }

  drawAvailable(): number {
    const townHall = this.townHall();
    return townHall ? townHall.level : 0;
  }

  keepAvailable(): number {
    const townHall = this.townHall();
    return townHall ? Math.ceil(townHall.level / 2) : 0;
  }

  drawPhase(): boolean {
    return !!this.game.scenario && gameManager.roundManager.firstRound && this.game.state === GameState.draw;
  }

  canDrawCard(deck: ChallengeDeck, force: boolean = false): boolean {
    return deck.current < deck.cards.length - 1 && (force || (this.drawPhase() && deck.current - deck.finished < this.drawAvailable()));
  }

  drawCard(deck: ChallengeDeck, force: boolean = false): boolean {
    if (!this.canDrawCard(deck, force)) {
      return false;
    }
    deck.current++;
    return true;
  }

  shuffleDeck(deck: ChallengeDeck, onlyUpcoming: boolean = false) {
    const current = deck.current;
    const finished = deck.finished;
    const restoreCards: ChallengeCard[] = onlyUpcoming && current > -1 ? deck.cards.splice(0, current + 1) : [];
    deck.current = -1;
    deck.finished = -1;
    deck.keep = [];
    gameManager.randomManager.shuffle(deck.cards);
    if (onlyUpcoming) {
      deck.current = current;
      deck.finished = finished;
      deck.cards.unshift(...restoreCards);
    }
  }

  removedCards(deck: ChallengeDeck): ChallengeCard[] {
    return gameManager.editionManager
      .challengesData(this.game.edition)
      .filter((challengeCard) => !deck.cards.some((other) => other.cardId === challengeCard.cardId));
  }

  canRestoreCard(deck: ChallengeDeck, card: ChallengeCard): boolean {
    return this.removedCards(deck).some((other) => other.cardId === card.cardId);
  }

  restoreCard(deck: ChallengeDeck, card: ChallengeCard): boolean {
    if (!this.canRestoreCard(deck, card)) {
      return false;
    }
    const index = gameManager.randomManager.int(deck.cards.length - deck.current) + deck.current + 1;
    deck.cards.splice(index, 0, card);
    return true;
  }

  getChallengeCard(identifier: Identifier): ChallengeCard | undefined {
    return gameManager.editionManager.challengesData(identifier.edition).find((challengeCard) => challengeCard.cardId === +identifier.name);
  }

  clearDrawn(deck: ChallengeDeck, keep: boolean = false) {
    const keepCards: ChallengeCard[] = [];
    if (keep) {
      deck.keep.forEach((index) => {
        keepCards.push(deck.cards[index]);
      });
    }
    if (deck.current >= 0) {
      for (let i = deck.current; i > deck.finished; i--) {
        if (!keep || !deck.keep.includes(i)) {
          const cards = deck.cards.splice(i, 1);
          if (cards.length) {
            deck.cards = [...deck.cards, cards[0]];
          }
        }
      }
      if (keep) {
        deck.keep = keepCards.map((card) => deck.cards.indexOf(card));
      } else {
        deck.keep = [];
      }
      deck.current = deck.finished + (keep ? deck.keep.length : 0);
    }
  }

  canMoveCard(deck: ChallengeDeck, fromList: string, fromIndex: number, toList: string, toIndex: number): boolean {
    const lengths: Record<string, number> = {
      finished: deck.finished + 1,
      discarded: deck.current - deck.finished,
      upcoming: deck.cards.length - deck.current - 1
    };
    if (lengths[fromList] === undefined || lengths[toList] === undefined || !Number.isInteger(fromIndex) || !Number.isInteger(toIndex)) {
      return false;
    }
    return fromIndex >= 0 && fromIndex < lengths[fromList] && toIndex >= 0 && toIndex <= lengths[toList] - (fromList === toList ? 1 : 0);
  }

  moveCard(deck: ChallengeDeck, fromList: string, fromIndex: number, toList: string, toIndex: number): boolean {
    if (!this.canMoveCard(deck, fromList, fromIndex, toList, toIndex)) {
      return false;
    }
    let from = 0;
    let to = 0;
    if (toList === 'upcoming') {
      if (fromList === 'upcoming') {
        from = fromIndex + deck.current + 1;
        to = toIndex + deck.current + 1;
      } else if (fromList === 'finished') {
        from = deck.finished - fromIndex;
        to = toIndex + deck.current;
        deck.finished--;
        deck.current--;
      } else {
        from = deck.current - fromIndex;
        to = toIndex + deck.current;
        deck.current--;
      }
    } else if (toList === 'discarded') {
      if (fromList === 'discarded') {
        from = deck.current - fromIndex;
        to = deck.current - toIndex;
      } else if (fromList === 'finished') {
        from = deck.finished - fromIndex;
        deck.finished--;
        to = deck.current - toIndex;
      } else {
        deck.current++;
        from = deck.current + fromIndex;
        to = deck.current - toIndex;
      }
    } else if (fromList === 'finished') {
      from = deck.finished - fromIndex;
      to = deck.finished - toIndex;
    } else if (fromList === 'discarded') {
      deck.finished++;
      from = deck.current - fromIndex;
      to = deck.finished - toIndex;
    } else {
      deck.finished++;
      deck.current++;
      from = deck.current + fromIndex;
      to = deck.finished - toIndex;
    }
    moveItemInArray(deck.cards, from, to);
    return true;
  }

  canRemoveCard(deck: ChallengeDeck, index: number): boolean {
    return Number.isInteger(index) && index >= 0 && index < deck.cards.length;
  }

  removeCard(deck: ChallengeDeck, index: number): boolean {
    if (!this.canRemoveCard(deck, index)) {
      return false;
    }
    if (index <= deck.finished) {
      deck.finished--;
    }
    if (index <= deck.current) {
      deck.current--;
    }
    deck.cards.splice(index, 1);
    return true;
  }

  swapKeptCards(deck: ChallengeDeck) {
    if (deck.keep.length > 1) {
      const card = deck.cards.splice(deck.keep[0], 1)[0];
      deck.cards.splice(deck.keep[1], 0, card);
    }
  }

  canToggleKeep(deck: ChallengeDeck, index: number, force: boolean = false): boolean {
    return (
      Number.isInteger(index) &&
      index > deck.finished &&
      index <= deck.current &&
      (deck.keep.includes(index) || this.keepAvailable() > 0) &&
      (force || this.drawPhase())
    );
  }

  toggleKeep(deck: ChallengeDeck, index: number, force: boolean = false): boolean {
    if (!this.canToggleKeep(deck, index, force)) {
      return false;
    }
    if (!deck.keep.includes(index)) {
      if (deck.keep.length >= this.keepAvailable()) {
        deck.keep.splice(0, deck.keep.length - this.keepAvailable() + 1);
      }
      deck.keep.push(index);
    } else {
      deck.keep.splice(deck.keep.indexOf(index), 1);
    }
    return true;
  }

  update() {
    this.available =
      gameManager.fhRules() &&
      this.game.party.buildings.find((buildingModel) => buildingModel.name === 'town-hall' && buildingModel.level) !== undefined;
    this.enabled =
      settingsManager.settings.fhChallenges &&
      gameManager.fhRules() &&
      this.game.party.buildings.find(
        (buildingModel) => buildingModel.name === 'town-hall' && buildingModel.level && buildingModel.state !== 'wrecked'
      ) !== undefined;
    this.apply = settingsManager.settings.fhChallengesApply && this.enabled;

    if (this.available && this.game.edition) {
      // build challenge deck if not present
      const challengeCards = gameManager.editionManager.challengesData(this.game.edition);
      if (challengeCards.length && (!this.game.challengeDeck || !this.game.challengeDeck.cards.length)) {
        this.game.challengeDeck = new ChallengeDeck();
        this.game.challengeDeck.cards = challengeCards.map((challengeCard) => {
          const card = new ChallengeCard(challengeCard.cardId, challengeCard.edition, challengeCard.automation);
          return card;
        });
        this.game.challengeDeck.current = -1;
        this.shuffleDeck(this.game.challengeDeck);
      }
    }

    if (this.apply) {
      this.applyCardsAlways();
    }
  }

  activeCards(edition: string | undefined = undefined, start: boolean = false): ChallengeCard[] {
    if (
      (this.available &&
        this.game.challengeDeck.cards.length &&
        this.game.challengeDeck.current > this.game.challengeDeck.finished &&
        (start || !gameManager.roundManager.firstRound)) ||
      this.game.state === GameState.next
    ) {
      return this.game.challengeDeck.cards
        .slice(this.game.challengeDeck.finished + 1, this.game.challengeDeck.current + 1)
        .filter((card) => gameManager.editionManager.isEditionRelevant(card.edition, edition));
    }
    return [];
  }

  activeCardIds(edition: string | undefined = undefined): number[] {
    return this.activeCards(edition).map((card) => card.cardId);
  }

  isActive(cardId: number, edition: string | undefined = undefined) {
    return this.activeCardIds(edition).includes(cardId);
  }

  applyCardsStart() {
    this.activeCards(undefined, true).forEach((card) => {
      this.applyCardStart(card);
    });
  }

  applyCardStart(card: ChallengeCard) {
    if (card.edition === 'fh') {
      switch (card.cardId) {
        case 1486:
          for (let i = 0; i < 3; i++) {
            gameManager.attackModifierManager.addModifier(
              this.game.monsterAttackModifierDeck,
              new AttackModifier(AttackModifierType.bless)
            );
          }
          break;
        case 1496:
          this.game.monsterAttackModifierDeck.cards = this.game.monsterAttackModifierDeck.cards.filter(
            (attackModifier) => attackModifier.type !== AttackModifierType.plus0
          );
          break;
        case 1503:
          const characters: CharacterData[] = gameManager.editionManager
            .charactersData('fh')
            .filter(
              (characterData) =>
                (!characterData.spoiler || this.game.unlockedCharacters.includes(characterData.edition + ':' + characterData.name)) &&
                !this.game.figures.find(
                  (figure) => figure instanceof Character && figure.edition === characterData.edition && figure.name === characterData.name
                )
            );
          if (characters.length) {
            const characterData = characters[gameManager.randomManager.int(characters.length)];
            const attackModifiers = gameManager.attackModifierBuildManager.perkCards(characterData);
            attackModifiers.forEach((am, index) => {
              am.id = 'challenge-fh-1503-' + characterData.name + '-' + index;
              am.character = true;
            });
            for (let i = 0; i < 5; i++) {
              const am = attackModifiers.splice(gameManager.randomManager.int(attackModifiers.length), 1)[0];
              this.game.monsterAttackModifierDeck.cards = [
                ...this.game.monsterAttackModifierDeck.cards,
                Object.assign(new AttackModifier(am.type), am)
              ];
            }
            gameManager.attackModifierManager.shuffleModifiers(this.game.monsterAttackModifierDeck);
          }
          break;
      }
    }
  }

  applyCardsAlways() {
    this.activeCards().forEach((card) => {
      this.applyCardAlways(card);
      this.game.figures.forEach((figure) => {
        if (figure instanceof Monster) {
          this.applyCardStatEffect(figure, card);
        }
      });
    });
  }

  applyCardAlways(card: ChallengeCard) {
    if (card.edition === 'fh') {
      switch (card.cardId) {
        case 1484:
          this.game.monsterAttackModifierDeck.cards.forEach((attackModifier) => {
            if (
              (!attackModifier.effects || attackModifier.effects.length === 0) &&
              (attackModifier.type === AttackModifierType.minus1 ||
                attackModifier.type === AttackModifierType.minus2 ||
                attackModifier.type === AttackModifierType.null)
            ) {
              attackModifier.effects = [];
              attackModifier.effects.push(new AttackModifierEffect(AttackModifierEffectType.changeType, AttackModifierType.plus0));
            }
          });
          break;
        case 1485:
          this.game.monsterAttackModifierDeck.cards.forEach((attackModifier) => {
            if ((!attackModifier.effects || attackModifier.effects.length === 0) && attackModifier.type === AttackModifierType.minus2) {
              attackModifier.effects = [];
              attackModifier.effects.push(new AttackModifierEffect(AttackModifierEffectType.changeType, AttackModifierType.double));
            }
          });
          break;
        case 1523:
          if (this.game.round === 2 && this.game.state === GameState.draw) {
            let hound = this.game.figures.find(
              (figure) => figure instanceof Monster && figure.edition === 'fh' && figure.name === 'hound'
            ) as Monster;
            if (!hound || !hound.tags.includes('challenge-fh-1523')) {
              if (!hound) {
                const houndData = gameManager.editionManager.monstersData('fh').find((monsterData) => monsterData.name === 'hound');
                if (houndData) {
                  hound = gameManager.monsterManager.addMonster(houndData, this.game.level);
                } else {
                  console.error('Unknown state: Monster Data for hound missing apply FH Challenge 1523!');
                }
              }
              if (hound) {
                hound.tags.push('challenge-fh-1523');
                for (let i = 0; i < gameManager.characterManager.characterCount(); i++) {
                  gameManager.monsterManager.spawnMonsterEntity(hound, MonsterType.normal);
                }
              }
            }
          }
          break;
      }
    }
  }

  applyCardsTrigger(cardId: number) {
    this.activeCards().forEach((card) => {
      if (card.cardId === cardId) {
        this.applyCardTrigger(card);
      }
    });
  }

  applyCardTrigger(card: ChallengeCard) {
    if (card.edition === 'fh') {
      switch (card.cardId) {
        case 1526:
          const entities = this.game.figures
            .filter((figure) => figure instanceof Monster)
            .map((monster) => monster.entities.filter((entity) => gameManager.entityManager.isAlive(entity)).length);
          if (entities.length && entities.reduce((a, b) => a + b) < gameManager.characterManager.characterCount()) {
            this.game.figures.forEach((figure) => {
              if (figure instanceof Monster) {
                figure.entities.forEach((entity) => {
                  if (gameManager.entityManager.isAlive(entity)) {
                    gameManager.conditionManager.addCondition(entity, figure, new Condition(ConditionName.ward));
                  }
                });
              }
            });
          }
          break;
      }
    }
  }

  applyCardStatEffect(monster: Monster, card: ChallengeCard) {
    const enemy = !monster.isAlly;
    if (card.edition === 'fh') {
      monster.entities.forEach((entity) => {
        if (gameManager.entityManager.isAlive(entity)) {
          switch (card.cardId) {
            case 1492:
              if (enemy && entity.health === entity.maxHealth && (!entity.tags || !entity.tags.includes('challenge-fh-1492'))) {
                entity.tags = entity.tags || [];
                entity.tags.push('challenge-fh-1492');
                entity.extraActionsPersistent.push(new Action(ActionType.retaliate, 2));
              } else if ((!enemy || entity.health < entity.maxHealth) && entity.tags && entity.tags.includes('challenge-fh-1492')) {
                const retaliateAction = entity.extraActionsPersistent.find(
                  (action) =>
                    action.type === ActionType.retaliate &&
                    action.value === 2 &&
                    action.valueType === ActionValueType.fixed &&
                    (!action.subActions || !action.subActions.length)
                );
                if (retaliateAction) {
                  entity.extraActionsPersistent.splice(entity.extraActionsPersistent.indexOf(retaliateAction), 1);
                }
                entity.tags = entity.tags.filter((tag) => tag !== 'challenge-fh-1492');
              }
              break;
            case 1493:
              if (enemy && (!entity.tags || !entity.tags.includes('challenge-fh-1493'))) {
                entity.tags = entity.tags || [];
                entity.tags.push('challenge-fh-1493');
                entity.maxHealth += Math.ceil(this.game.level / 2);
                entity.health += Math.ceil(this.game.level / 2);
              }

              break;
            case 1496:
              if (
                enemy &&
                (!entity.immunities || !entity.immunities.includes(ConditionName.curse)) &&
                (!entity.tags || !entity.tags.includes('challenge-fh-1496'))
              ) {
                entity.tags = entity.tags || [];
                entity.tags.push('challenge-fh-1496');
                entity.immunities.push(ConditionName.curse);
              }
              break;
            case 1515:
              const elitePresent = monster.entities.find(
                (entity) => entity.type === MonsterType.elite && gameManager.entityManager.isAlive(entity)
              );
              if (
                enemy &&
                elitePresent &&
                entity.type === MonsterType.normal &&
                (!entity.tags || !entity.tags.includes('challenge-fh-1515'))
              ) {
                entity.tags = entity.tags || [];
                entity.tags.push('challenge-fh-1515');
                const challengeShield1515 = entity.extraActionsPersistent.find((action) => action.type === ActionType.shield);
                if (!challengeShield1515) {
                  entity.extraActionsPersistent.push(new Action(ActionType.shield, 1));
                } else {
                  challengeShield1515.value = EntityValueFunction(challengeShield1515.value) + 1;
                }
              } else if ((!enemy || !elitePresent) && entity.tags && entity.tags.includes('challenge-fh-1515')) {
                const challengeShield1515Remove = entity.extraActionsPersistent.find((action) => action.type === ActionType.shield);
                if (challengeShield1515Remove) {
                  if (EntityValueFunction(challengeShield1515Remove.value) <= 1) {
                    entity.extraActionsPersistent = entity.extraActionsPersistent.filter((action) => action.type !== ActionType.shield);
                  } else {
                    challengeShield1515Remove.value = EntityValueFunction(challengeShield1515Remove.value) - 1;
                  }
                }
                entity.tags = entity.tags.filter((tag) => tag !== 'challenge-fh-1515');
              }
              break;
            case 1524:
              const negativeConditions = entity.entityConditions.filter(
                (condition) =>
                  condition.types.includes(ConditionType.negative) && condition.state !== EntityConditionState.removed && !condition.expired
              );
              if (enemy && !negativeConditions.length && (!entity.tags || !entity.tags.includes('challenge-fh-1524'))) {
                entity.tags = entity.tags || [];
                entity.tags.push('challenge-fh-1524');
                const challengeShield1524 = entity.extraActionsPersistent.find((action) => action.type === ActionType.shield);
                if (!challengeShield1524) {
                  entity.extraActionsPersistent.push(new Action(ActionType.shield, 1));
                } else {
                  challengeShield1524.value = EntityValueFunction(challengeShield1524.value) + 1;
                }
              } else if ((!enemy || negativeConditions.length) && entity.tags && entity.tags.includes('challenge-fh-1524')) {
                const challengeShield1524Remove = entity.extraActionsPersistent.find((action) => action.type === ActionType.shield);
                if (challengeShield1524Remove) {
                  if (EntityValueFunction(challengeShield1524Remove.value) <= 1) {
                    entity.extraActionsPersistent = entity.extraActionsPersistent.filter((action) => action.type !== ActionType.shield);
                  } else {
                    challengeShield1524Remove.value = EntityValueFunction(challengeShield1524Remove.value) - 1;
                  }
                }
                entity.tags = entity.tags.filter((tag) => tag !== 'challenge-fh-1524');
              }
              break;
          }
        }
      });
    }
  }
}
