import { Dialog, DIALOG_DATA, DialogRef } from '@angular/cdk/dialog';
import { NgClass } from '@angular/common';
import { Component, inject } from '@angular/core';
import { GameManager } from 'src/app/game/businesslogic/GameManager';
import { gameManager, settingsManager } from 'src/app/game/businesslogic/Managers';
import { SettingsManager } from 'src/app/game/businesslogic/SettingsManager';
import { Character } from 'src/app/game/model/Character';
import { ItemData } from 'src/app/game/model/data/ItemData';
import { openEventRandomItemDialog } from 'src/app/ui/figures/entities-menu/random-item/random-item-dialog';
import { ItemDialogComponent } from 'src/app/ui/figures/items/dialog/item-dialog';
import { ItemComponent } from 'src/app/ui/figures/items/item/item';
import { GhsLabelDirective } from 'src/app/ui/helper/label';
import { ghsDialogClosingHelper } from 'src/app/ui/helper/Static';

export function openLootRandomItemDialog(dialog: Dialog, item: ItemData, character: Character, index: number) {
  if (!gameManager.lootManager.applyRandomItemEnabled()) {
    openEventRandomItemDialog(dialog, item);
    return;
  }

  dialog
    .open(LootRandomItemDialogComponent, {
      panelClass: ['dialog'],
      data: { item: item, character: character }
    })
    .closed.subscribe({
      next: (result) => {
        const characterName = gameManager.characterManager.characterName(character, true, true);
        if (result && gameManager.lootManager.canApplyRandomItem(character, index)) {
          gameManager.stateManager.before('lootRandomItem', item.id, item.edition, item.name, characterName);
          gameManager.lootManager.applyRandomItem(character, index, item);
          gameManager.stateManager.after();
        } else if (character.lootCards.includes(index)) {
          const loot = gameManager.game.lootDeck.cards[index];
          gameManager.stateManager.before(
            'removeLootCard',
            characterName,
            'game.loot.' + loot.type,
            gameManager.lootManager.getValue(loot)
          );
          gameManager.lootManager.removeLootCard(character, index);
          gameManager.stateManager.after();
        }
      }
    });
}

@Component({
  imports: [NgClass, GhsLabelDirective, ItemComponent],
  selector: 'ghs-random-item-dialog',
  templateUrl: './random-item-dialog.html',
  styleUrls: ['./random-item-dialog.scss']
})
export class LootRandomItemDialogComponent {
  private dialogRef = inject(DialogRef);
  private dialog = inject(Dialog);

  settingsManager: SettingsManager = settingsManager;
  gameManager: GameManager = gameManager;
  item: ItemData;
  character: Character;
  autoSell: boolean = false;

  data: { item: ItemData; character: Character } = inject(DIALOG_DATA);

  constructor() {
    this.item = this.data.item;
    this.character = this.data.character;
    this.autoSell =
      this.character !== undefined &&
      this.character.progress.items.find((existing) => existing.name === '' + this.item.id && existing.edition === this.item.edition) !=
        undefined;
  }

  close() {
    ghsDialogClosingHelper(this.dialogRef);
  }

  openDialog() {
    this.dialog.open(ItemDialogComponent, {
      panelClass: ['fullscreen-panel'],
      disableClose: true,
      data: { item: this.item }
    });
  }

  apply() {
    ghsDialogClosingHelper(this.dialogRef, this.item);
  }
}
